System.arraycopy(arr, 2, newArr, 3, 2);      // Copy rest
// newArr = {1, 2, 3, 4, 5}

// 2. Remove element
int[] arr = {1, 2, 3, 4, 5};
int[] newArr = new int[4];
System.arraycopy(arr, 0, newArr, 0, 2);      // Copy before index 2
System.arraycopy(arr, 3, newArr, 2, 2);      // Copy after index 2
// newArr = {1, 2, 4, 5} (removed 3)
```

